function routeAccessPoints(spec: WestVirginiaRouteSpec): RiverRouteAccessPoint[] {
  return [
    { id: `${spec.id}-put-in`, name: spec.putIn.name, latitude: spec.putIn.latitude, longitude: spec.putIn.longitude, mileFromStart: 0, segmentKind: 'transition', note: 'Verified public access named in the research dossier.' },
    { id: `${spec.id}-take-out`, name: spec.takeOut.name, latitude: spec.takeOut.latitude, longitude: spec.takeOut.longitude, mileFromStart: spec.miles, segmentKind: 'transition', note: 'Verified public take-out named in the research dossier.' },
  ];
}

function makeRoute(spec: WestVirginiaRouteSpec): River {
  const accessPoints = routeAccessPoints(spec);
  const gaugeSource = {
    id: `usgs-${spec.gaugeSiteId}`,
    provider: 'usgs' as const,
    siteId: spec.gaugeSiteId,
    metric: spec.gaugeMetric,
    unit: spec.gaugeUnit,
    kind: spec.gaugeKind ?? 'direct',
    siteName: spec.gaugeSiteName,
    detailUrl: spec.gaugeDetailUrl,
    hydrographUrl: spec.gaugeHydrographUrl,
  };
  const sourceLinks = [...spec.sourceLinks];
  const logistics = {
    distanceLabel: spec.distance,
    estimatedPaddleTime: `About ${Math.max(2, Math.ceil(spec.miles / 2))}–${Math.max(4, Math.ceil(spec.miles / 1.3))} hr depending on flow, scouting, breaks, and shuttle timing`,
    shuttle: spec.shuttle,
    permits: 'No route-specific permit is published for the named public endpoints. Follow current West Virginia boating/PFD rules, posted access rules, and any closure or water-quality notice.',
    camping: spec.camping,
    campingClassification: spec.campingClassification,
    summary: spec.logisticsSummary,
    accessCaveats: spec.accessCaveats,
    watchFor: spec.watchFor,
  };
  const gaugePlanningNote = spec.gaugeSiteId === '03185400'
    ? ' Same-river proxy only: the Thurmond telemetry is not a route-endpoint measurement, so pair it with a same-day visual, rainfall, and access check.'
      : spec.gaugeSiteId === '01611500'
      ? ' Downstream same-river proxy: Great Cacapon telemetry is below this upper reach, so pair it with a same-day visual, rainfall, and access check.'
      : spec.gaugeSiteId === '03202300' && spec.gaugeKind === 'proxy'
        ? ' Downstream same-river proxy: Pineville telemetry is below the Mullens–Pineville reach, so pair it with a same-day upper-river visual, rainfall, debris, and access check.'
      : spec.gaugeSiteId === '03198500'
      ? spec.gaugeKind === 'proxy'
          ? (spec.id === 'wv-big-coal-dartmont-sproul' || spec.id === 'wv-big-coal-sproul-lions-park'
            ? ' Upstream same-river proxy: Ashford telemetry is above these Big Coal reaches, so pair it with a same-day visual, rainfall, and access check.'
            : ' Downstream same-river proxy: Ashford telemetry is below these Big Coal reaches, so pair it with a same-day visual, rainfall, and access check.')
          : ' Same-reach gauge: Ashford telemetry is close to this Big Coal segment, but pair it with a same-day visual, rainfall, and access check.'
      : spec.gaugeSiteId === '03058975' && spec.gaugeKind === 'proxy'
        ? ' Downstream same-river proxy: Mount Clare telemetry is below the Good Hope–West Milford reach, so pair it with a same-day visual, rainfall, debris, and access check.'
      : spec.gaugeSiteId === '03061000' && spec.gaugeKind === 'proxy'
        ? ' Upstream same-river proxy: Enterprise telemetry is above the Worthington–Monongah reach, so pair it with a same-day visual, rainfall, debris, and access check.'
      : spec.gaugeSiteId === '03184000' && spec.gaugeKind === 'proxy'
        ? ' Same-river upstream proxy: Hilldale telemetry is upstream of the Willowwood–Bellepoint confluence reach, so pair it with a same-day visual, rainfall, water-quality, and access check.'
      : spec.gaugeSiteId === '03199000' && spec.gaugeKind === 'proxy'
        ? ' Upstream same-river proxy: Danville telemetry is above this Little Coal reach, so pair it with a same-day visual, rainfall, and access check.'
      : spec.gaugeSiteId === '03200500'
          ? spec.gaugeKind === 'proxy'
            ? (spec.id === 'wv-coal-forks-lions-park'
              ? ' Downstream same-river proxy: Tornado telemetry is below this Coal/Little Coal confluence reach, so pair it with a same-day visual, rainfall, and access check.'
              : ' Upstream same-river proxy: Tornado telemetry is above this Coal reach, so pair it with a same-day visual, rainfall, and access check.')
            : ' Same-reach gauge: Tornado telemetry is close to the Meadowood put-in, but pair it with a same-day visual, rainfall, and access check.'
        : '';
  return {
    id: spec.id,
    slug: spec.id,
    name: spec.name,
    riverId: spec.riverId,
    reach: spec.reach,
    aliases: spec.aliases,
    state: 'West Virginia',
    region: spec.region,
    routeType: spec.routeType ?? 'whitewater',
    summary: `${spec.name} ${spec.reach} is a ${spec.distance} ${spec.classLabel} run documented by ${spec.sourceLinks.some((source) => source.provider === 'american_whitewater') ? 'American Whitewater and official access partners' : 'official route and access sources'}.`,
    statusText: `Use USGS ${spec.gaugeSiteId} as the live planning gauge. Recheck current ${spec.gaugeUnit === 'cfs' ? 'discharge' : 'stage'}, trend, rainfall, access, shuttle roads, hazards, and daylight immediately before launch.${gaugePlanningNote}`,
    latitude: (spec.putIn.latitude + spec.takeOut.latitude) / 2,
    longitude: (spec.putIn.longitude + spec.takeOut.longitude) / 2,
    putIn: spec.putIn,
    takeOut: spec.takeOut,
    logistics,
    accessPoints,
    safetyProfile: { riskLevel: spec.riskLevel, hazards: spec.hazards, safetyNotes: spec.safetyNotes, reviewStatus: 'reviewed' },
    gaugeSource,
    profile: {
      thresholdModel: 'two-sided', idealMin: spec.idealMin, idealMax: spec.idealMax, tooLow: spec.tooLow, tooHigh: spec.tooHigh,
      thresholdSource: { label: spec.thresholdLabel, url: spec.thresholdUrl, provider: spec.thresholdProvider },
      thresholdSourceStrength: spec.thresholdStrength,
      rainfallSensitivity: 'high', seasonMonths: [4, 5, 6, 7, 8, 9, 10], seasonNotes: spec.seasonNotes,
      difficulty: spec.difficulty, difficultyNotes: spec.difficultyNotes, confidenceNotes: spec.confidenceNotes,
    },
    evidenceNotes: [...spec.evidenceNotes, { label: 'Gauge', value: `USGS ${spec.gaugeSiteId} ${spec.gaugeMetric === 'discharge_cfs' ? 'discharge' : 'stage'} telemetry`, note: spec.gaugeSiteId === '03185400' ? 'Official same-river proxy used for the route planning screen; it is not a route-endpoint measurement. Verify current value and trend alongside weather, visual conditions, and access.' : spec.gaugeSiteId === '01611500' ? 'Official downstream same-river proxy used for the upper Cacapon planning screen; verify current value and trend alongside local rainfall and a visual check.' : spec.gaugeSiteId === '03184000' && spec.gaugeKind === 'proxy' ? 'Official upstream same-river proxy used for the lower Greenbrier/confluence planning screen; verify current value and trend alongside local rainfall, water quality, visual conditions, and access.' : spec.gaugeSiteId === '03202300' && spec.gaugeKind === 'proxy' ? 'Official downstream same-river proxy used for the upper Guyandotte planning screen; verify current value and trend alongside local rainfall, debris, visual conditions, and access.' : 'Official same-river gauge used for the route planning screen; verify current value and trend before launch.', sourceUrl: spec.gaugeHydrographUrl }],
    sourceLinks,
    scoreEligibility: 'scored',
  };
}

export const westVirginiaRoutes: River[] = [...routeSpecs, ...additionalSpecs, ...cheatSpecs, ...strategicNextSpecs, ...elkSaturationSpecs, ...coalSaturationSpecs, ...westForkSaturationSpecs, ...greenbrierSaturationSpecs, ...guyandotteSaturationSpecs, ...gauleySaturationSpecs].map(makeRoute);
